import com.motohub.next.Store;
import org.json.*;
public class StoreTest {
 static int passed=0;static void check(boolean x,String n){if(!x)throw new AssertionError(n);System.out.println("PASS "+n);passed++;}
 interface Task{void run()throws Exception;}static void rejects(Task t,String n)throws Exception{boolean rejected=false;try{t.run();}catch(Exception e){rejected=true;}check(rejected,n);}
 public static void main(String[] args)throws Exception{
 JSONObject d=Store.empty();check(d.getJSONArray("vehicles").length()==0,"empty initial data");JSONObject b=new JSONObject("{\"id\":\"b\",\"name\":\"테스트\",\"odo\":4800}");Store.upsert(d,"vehicles",b);check(Store.parse(d.toString()).getJSONArray("vehicles").length()==1,"vehicle round trip");b.put("odo",5100);Store.upsert(d,"vehicles",b);check(d.getJSONArray("vehicles").length()==1,"edit no duplicate");
 JSONObject e=new JSONObject("{\"id\":\"e\",\"vehicleId\":\"b\",\"amount\":15000,\"date\":\"2026-10-15\"}");Store.upsert(d,"expenses",e);JSONObject s=new JSONObject("{\"id\":\"s\",\"vehicleId\":\"b\",\"cost\":25000,\"date\":\"2026-10-10\",\"nextKm\":5000}");Store.upsert(d,"services",s);check(Store.monthly(d,"2026-10")==40000,"monthly total");check(Store.monthly(d,"2026-09")==0,"month isolation");check(Store.due(s,b,"2026-10-15"),"mileage due");s.put("nextKm",6000).put("nextDate","2026-10-14");check(Store.due(s,b,"2026-10-15"),"date due");
 check(Store.safeUrl("https://example.com/1"),"https allowed");check(!Store.safeUrl("javascript:alert(1)"),"script blocked");check(!Store.safeUrl("file:///private"),"file blocked");check(!Store.safeUrl("https://user:secret@example.com"),"credentials blocked");check(Store.canonicalUrl("https://example.com/1/#abc").equals("https://example.com/1"),"URL normalization");
 d.put("extra",new JSONObject("{\"x\":1}"));d.getJSONArray("routes").put(new JSONObject("{\"id\":\"r\",\"points\":[{\"lat\":37,\"lon\":127}]}"));JSONObject copy=Store.parse(d.toString());check(copy.getJSONObject("extra").getInt("x")==1,"unknown fields kept");check(copy.getJSONArray("routes").getJSONObject(0).getJSONArray("points").length()==1,"GPX points kept");JSONObject legacy=new JSONObject(d.toString()).put("version",1);legacy.remove("gear");check(Store.parse(legacy.toString()).getInt("version")==3,"v1 migration");
 rejects(()->Store.parse("broken"),"bad JSON rejected");JSONObject dup=new JSONObject(d.toString());dup.getJSONArray("vehicles").put(b);rejects(()->Store.parse(dup.toString()),"duplicate ID rejected");JSONObject neg=new JSONObject(d.toString());neg.getJSONArray("expenses").getJSONObject(0).put("amount",-1);rejects(()->Store.parse(neg.toString()),"negative money rejected");JSONObject orphan=new JSONObject(d.toString());orphan.getJSONArray("expenses").getJSONObject(0).put("vehicleId","missing");rejects(()->Store.parse(orphan.toString()),"orphan rejected");rejects(()->Store.parse(new JSONObject(d.toString()).put("version",99).toString()),"future version rejected");rejects(()->Store.validateDate("2026-02-30"),"invalid calendar date");JSONObject date=new JSONObject(d.toString());date.getJSONArray("expenses").getJSONObject(0).put("date","2026-99-01");rejects(()->Store.parse(date.toString()),"backup bad date rejected");JSONObject hist=new JSONObject(d.toString());hist.getJSONArray("listings").put(new JSONObject("{\"id\":\"bad\",\"priceHistory\":[null]}"));rejects(()->Store.parse(hist.toString()),"nested history validated");Store.remove(copy,"expenses","e");check(copy.getJSONArray("expenses").length()==0,"delete");check(d.getJSONArray("expenses").length()==1,"copy isolated");System.out.println("TOTAL "+passed+" passed");
 }
}
